// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {createTypeColorRegistry} from "../../../main/frontend/graph-explorer/graph-type-colors.ts";

test("the first types seen get distinct colours, and a type keeps its colour", () => {
  const colorOf = createTypeColorRegistry(6);
  const types = ["urn:Person", "urn:City", "urn:Project", "urn:Organization", "urn:Country", "urn:Event"];
  const indexes = types.map(colorOf);
  assert.deepEqual(indexes, [0, 1, 2, 3, 4, 5]);
  assert.equal(colorOf("urn:City"), 1);
  assert.equal(colorOf("urn:Seventh"), 0);
});
